-- Closed verified-purchase/financial fixtures. No hosted calls or generated media.
create temporary table checks(n integer);insert into checks values(0);grant all on checks to service_role,authenticated;
create function pg_temp.ok(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception'PAID-QUALITY FAIL: %',label;end if;update checks set n=n+1;end$$;
create function pg_temp.refuse(command text,needle text,label text)returns void language plpgsql as $$begin begin execute command;exception when others then if position(needle in sqlerrm)>0 then perform pg_temp.ok(true,label);return;end if;raise;end;raise exception'PAID-QUALITY FAIL: allowed %',label;end$$;
create function pg_temp.purchase(plan text,annual boolean default false)returns void language plpgsql as $$begin
 perform public.apply_apple_entitlement_v2((select org from bf),(select actor from bf),'paid-quality-original-'||plan||annual,'paid-quality-transaction-'||plan||annual,'com.rendprop.app.'||plan||case when annual then'.annual'else'.monthly'end,plan,'Production','active',now()+case when annual then interval'355 days'else interval'29 days'end,true,'DID_RENEW',now()-case when annual then interval'10 days'else interval'1 day'end,now()+interval'1 second',now()+interval'1 second',now()+interval'1 second');
end$$;
create function pg_temp.recipe(i integer,n integer default 20)returns jsonb language sql as $$select jsonb_set(jsonb_set(jsonb_set(m,'{operation_id}',to_jsonb(('f4900000-0000-4000-8000-'||lpad(i::text,12,'0'))::text)),'{sources}',(select jsonb_agg(value order by ord)from jsonb_array_elements(m->'sources')with ordinality e(value,ord)where ord<=n)),'{presentation,shot_labels}',(select jsonb_agg(null::text)from generate_series(1,n)))from bm$$;
create function pg_temp.hold(k text,stage text,cents numeric)returns jsonb language sql as $$select public.serving_cost_reserve((select actor from bf),(select org from bf),k,stage,'gemini','closed-cost-fixture',repeat('a',64),cents,'closed-exact-quote-fixture')$$;
select pg_temp.ok((select value->>'enabled'='false'from app_config where key='paid_quality_processing'),'policy ships OFF');
select pg_temp.ok(not has_function_privilege('authenticated','public.paid_quality_processing_budget(uuid)','execute')and not has_function_privilege('anon','public.paid_quality_processing_budget(uuid)','execute'),'allowance helper is service-only');
select pg_temp.ok(has_function_privilege('authenticated','public.org_entitlement(uuid)','execute')and has_function_privilege('authenticated','public.org_month_spend_cents(uuid)','execute')and not has_function_privilege('authenticated','public.plan_serving_ceiling(uuid)','execute'),'existing client read grants preserved without exposing financial controls');
update app_config set value='{"mode":"ceiling","free_published_listings":1}'where key='serving_mode';
update app_config set value=jsonb_set(value,'{enabled}','true')where key='property_video_jobs';
set local role service_role;select pg_temp.purchase('starter');
select pg_temp.ok(paid_quality_processing_budget((select org from bf))=0,'OFF policy never raises an ordinary paid allowance');
select pg_temp.ok((org_entitlement((select org from bf))).cogs_ceiling_cents=2032,'original Starter COGS cap preserved while OFF');
select pg_temp.refuse($q$select property_video_recipe_capacity((select actor from bf),(select listing from bf),20,4403.9552)$q$,'RP402:','reproduces original20-photo funding dead end');
reset role;update app_config set value=jsonb_set(value,'{enabled}','true')where key='paid_quality_processing';set local role service_role;
select pg_temp.ok(paid_quality_processing_budget((select org from bf))=0,'policy also requires a reviewed quality profile activation');
reset role;update app_config set value='{"enabled":true,"profile":"fal-kling3-4k-v1"}'where key='property_video_quality';set local role service_role;
select pg_temp.ok(paid_quality_processing_budget((select org from bf))=6500,'verified ordinary paid Starter gets bounded65-dollar allowance');
select pg_temp.ok((org_entitlement((select org from bf))).cogs_ceiling_cents=6500 and(plan_serving_ceiling((select org from bf))->>'ceiling_cents')::numeric=6500,'COGS and atomic serving agree');
select pg_temp.ok((org_entitlement((select org from bf))).price_cents=4900 and(org_entitlement((select org from bf))).reels_per_month=30 and(org_entitlement((select org from bf))).photo_edits_per_month=100,'retail price and monthly feature quotas unchanged');
select pg_temp.ok(plan_serving_ceiling((select org from bf))->>'window'='apple_term'and(plan_serving_ceiling((select org from bf))->>'period_end')::timestamptz=now()+interval'29 days','actual Apple paid service period retained');
select pg_temp.ok(not org_has_internal_testing_grant((select org from bf))and not org_has_private_internal_testing((select org from bf)),'positive proof has no private sponsorship');
-- Prior unrelated expense, uncertain liability and quotas are intentionally used.
reset role;insert into cost_ledger(org_id,feature,provider,model,total_cents,meta,created_at)values((select org from bf),'copy','openai','prior-paid-term-fixture',6500,'{}',now()-interval'2 days');
select pg_temp.ok(org_month_spend_cents((select org from bf))=0,'previous paid term booked cost never blocks a renewed service window');
insert into cost_ledger(org_id,feature,provider,model,total_cents,meta)values((select org from bf),'copy','openai','earlier-closed-fixture',100,'{}');
insert into rate_limits(key,window_start,count,window_seconds)values('aiphotomo:'||(select org from bf),now(),2,2592000),('reelmo:'||(select org from bf),now(),3,2592000);set local role service_role;
select pg_temp.hold('paid-quality-prior-unknown','prior:unknown',50);
reset role;update serving_cost_reservations set created_at=now()-interval'2 days'where request_key='paid-quality-prior-unknown';set local role service_role;
select pg_temp.ok(org_month_spend_cents((select org from bf))=150,'current booked cost and prior-term uncertain hold both count');
-- Current complete worst-tier Pro generation+photo QC quotes for40 edits.
do $$declare i integer;e public.plan_entitlements;begin e:=org_entitlement((select org from bf));for i in 1..40 loop
 perform pg_temp.ok((bump_rate_receipt('aiphotomo:'||(select org from bf),2592000,e.photo_edits_per_month,1)->>'accepted')::boolean,'ordinary photo admission '||i);
 perform pg_temp.hold('paid-quality-photo-'||i,'photo.generate',33.8304);
 perform pg_temp.hold('paid-quality-photo-'||i,'photo.qc',10.8624);
end loop;end$$;
select pg_temp.ok((serving_envelope_state((select org from bf))->>'held_cents')::numeric=1837.71,'all photo+prior uncertain holds counted');
create temporary table admitted as select property_video_job_admit((select actor from bf),pg_temp.recipe(1),4403.9552,'fal-kling3-4k-v1')a;grant select on admitted to service_role;
select pg_temp.ok((select a->>'accepted'='true'and a#>>'{job,source_count}'='20'from admitted),'ordinary paid20-photo video passes full recipe after40 photo edits');
do $$declare i integer;e public.plan_entitlements;r jsonb;begin e:=org_entitlement((select org from bf));for i in 1..20 loop
 perform pg_temp.ok((bump_rate_receipt('reelmo:'||(select org from bf),2592000,e.reels_per_month,1)->>'accepted')::boolean,'ordinary clip admission '||i);
 r:=app_video_cost_reserve((select actor from bf),(select org from bf),'paid-quality-video-'||i,'reel','fal','fal-ai/kling-video/v3/4k/image-to-video',repeat('b',64),210,5,42,'{"task":"video.reel_clip"}');
 perform pg_temp.ok((r->>'reserved')::boolean,'actual priced clip hold '||i);
 perform pg_temp.hold('paid-quality-video-'||i,'reel',210);
 -- Rounded UP from conservative complete all-route/retry QC bound10.19776.
 perform pg_temp.hold('paid-quality-video-'||i,'video.qc',10.1978);
end loop;end$$;
select pg_temp.ok((serving_envelope_state((select org from bf))->>'spent_cents')::numeric=100 and(serving_envelope_state((select org from bf))->>'held_cents')::numeric=6241.67,'legacy video and serving holds net once; every all-AI liability counts');
select pg_temp.ok((serving_envelope_state((select org from bf))->>'available_cents')::numeric=158.33,'customer balance uses same bounded allowance minus old spend+holds');
select pg_temp.ok((select count=42 from rate_limits where key='aiphotomo:'||(select org from bf))and(select count=23 from rate_limits where key='reelmo:'||(select org from bf)),'old feature counters were not reset');
reset role;set local role authenticated;select set_config('request.jwt.claim.sub',(select actor::text from bf),true);
select pg_temp.ok(org_month_spend_cents((select org from bf))=6341.668,'authenticated owner sees same actual paid-period spend');
select pg_temp.ok(org_month_spend_cents((select other_org from bf))=0,'authenticated reader cannot see a foreign wallet');
reset role;set local role service_role;
select pg_temp.refuse($q$select pg_temp.hold('paid-quality-over-budget','test',158.3321)$q$,'RP402:','real atomic gate refuses above remaining balance');
select pg_temp.refuse($q$select pg_temp.hold('paid-quality-video-1','reel',210)$q$,'RP409:','same paid attempt cannot reserve again');
select pg_temp.refuse($q$select app_video_cost_reserve((select actor from bf),(select org from bf),'paid-quality-video-1','reel','fal','fal-ai/kling-video/v3/4k/image-to-video',repeat('b',64),210,5,42,'{"task":"video.reel_clip"}')$q$,'RP409:','accepted provider operation cannot regenerate');
select pg_temp.ok((property_video_job_admit((select actor from bf),pg_temp.recipe(1),null,'unknown')#>>'{job,id}')=(select a#>>'{job,id}'from admitted),'saved job replay stays same after spending');
select pg_temp.refuse($q$select property_video_recipe_capacity((select actor from bf),(select listing from bf),8,1762)$q$,'remain in the current plan allowance','clip quota still counts earlier clips');
select pg_temp.refuse($q$select serving_cost_reserve((select other from bf),(select org from bf),'paid-quality-foreign','test','fal','fixture',repeat('a',64),1,'fixture')$q$,'RP403:','foreign actor never gets paid allowance access');
select pg_temp.purchase('pro');select pg_temp.ok(paid_quality_processing_budget((select org from bf))=12000 and(org_entitlement((select org from bf))).reels_per_month=60 and(plan_serving_ceiling((select org from bf))->>'ceiling_cents')::numeric=12000,'Pro120-dollar budget and unchanged60 clips');
select pg_temp.purchase('team');select pg_temp.ok(paid_quality_processing_budget((select org from bf))=30000 and(org_entitlement((select org from bf))).reels_per_month=150 and(plan_serving_ceiling((select org from bf))->>'ceiling_cents')::numeric=30000,'Team300-dollar budget and unchanged150 clips');
select pg_temp.purchase('starter',true);select pg_temp.ok(paid_quality_processing_budget((select org from bf))=6500 and plan_serving_ceiling((select org from bf))->>'window'='apple_slice'and plan_serving_ceiling((select org from bf))->'period_start'=plan_serving_ceiling_before_team((select org from bf))->'period_start'and plan_serving_ceiling((select org from bf))->'period_end'=plan_serving_ceiling_before_team((select org from bf))->'period_end','annual allowance uses original paid monthly slice');
reset role;update orgs set plan_expires_at=plan_expires_at+interval'1 hour'where id=(select org from bf);set local role service_role;
select pg_temp.ok(paid_quality_processing_budget((select org from bf))=0,'historical receipt cannot fund a different current paid deadline');
reset role;update orgs set plan_expires_at=plan_expires_at-interval'1 hour'where id=(select org from bf);set local role service_role;
reset role;update apple_subscriptions set transaction_signed_at=null where org_id=(select org from bf);set local role service_role;
select pg_temp.ok(paid_quality_processing_budget((select org from bf))=0,'missing signed transaction cannot grant paid processing');
reset role;update apple_subscriptions set transaction_signed_at=now()where org_id=(select org from bf);set local role service_role;
reset role;update apple_subscriptions set status='grace'where org_id=(select org from bf);set local role service_role;
select pg_temp.ok(paid_quality_processing_budget((select org from bf))=0 and(plan_serving_ceiling((select org from bf))->>'ceiling_cents')::numeric=0,'commercial grace receives no new subsidy');
reset role;update apple_subscriptions set status='active',expires_at=now()-interval'1 day'where org_id=(select org from bf);set local role service_role;
select pg_temp.ok(paid_quality_processing_budget((select org from bf))=0,'expired paid receipt cannot gain a new allowance');
reset role;update apple_subscriptions set status='active',expires_at=now()+interval'7 days',transaction_purchased_at=now()where org_id=(select org from bf);set local role service_role;
select pg_temp.ok(paid_quality_processing_budget((select org from bf))=0,'introductory term remains on existing bounded trial policy');
reset role;update apple_subscriptions set expires_at=now()+interval'29 days',transaction_purchased_at=now()-interval'1 day',environment='Sandbox'where org_id=(select org from bf);set local role service_role;
select pg_temp.ok(paid_quality_processing_budget((select org from bf))=0,'Sandbox receipt cannot masquerade as paid production money');
reset role;update orgs set plan='free',plan_source=null,plan_expires_at=null where id=(select org from bf);set local role service_role;
select pg_temp.ok(paid_quality_processing_budget((select org from bf))=0 and(org_entitlement((select org from bf))).cogs_ceiling_cents=300,'ordinary Free lifetime boundary unchanged');
reset role;update orgs set plan='trial',plan_source='trial',trial_ends_at=now()+interval'7 days'where id=(select org from bf);set local role service_role;
select pg_temp.ok(paid_quality_processing_budget((select org from bf))=0 and(org_entitlement((select org from bf))).reels_per_month=0 and(plan_serving_ceiling((select org from bf))->>'ceiling_cents')::numeric=500,'unverified trial does not receive new funds or quota');
reset role;update orgs set plan='starter',plan_source='manual'where id=(select org from bf);set local role service_role;
select pg_temp.ok(paid_quality_processing_budget((select org from bf))=0,'manual or claimed plan is not a paid receipt');
reset role;update plan_entitlements set cogs_ceiling_cents=50000 where plan='starter';set local role service_role;
select pg_temp.ok((org_entitlement((select org from bf))).cogs_ceiling_cents=50000 and(plan_serving_ceiling((select org from bf))->>'ceiling_cents')::numeric=50000,'higher existing custom allowance never lowered');
reset role;create temporary table saved_policy as select value from app_config where key='paid_quality_processing';update app_config set value=value-'policy'where key='paid_quality_processing';set local role service_role;
select pg_temp.refuse($q$select paid_quality_processing_budget((select org from bf))$q$,'RP503:','missing policy identity never grants processing');
reset role;update app_config set value=jsonb_set((select value from saved_policy),'{policy}','null'::jsonb)where key='paid_quality_processing';set local role service_role;
select pg_temp.refuse($q$select paid_quality_processing_budget((select org from bf))$q$,'RP503:','null policy identity never grants processing');
reset role;update app_config set value=(select value from saved_policy)where key='paid_quality_processing';set local role service_role;
reset role;update app_config set value='{"mode":"funded"}'where key='serving_mode';set local role service_role;
select pg_temp.ok(paid_quality_processing_budget((select org from bf))=0,'funded-slice mode is unchanged');
reset role;select jsonb_build_object('passed',true,'assertions',(select n from checks));rollback;
